import os
import json
import uuid
import datetime
from pathlib import Path
import jsonschema
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("josh_supervisor")

MISSIONS_DIR = Path(os.path.expanduser("~/.gemini/missions"))
MISSIONS_DIR.mkdir(parents=True, exist_ok=True)
SCHEMA_PATH = Path("C:/dev/JoshSupervisor/schema.json")

PROGRAMMES_DIR = Path(os.path.expanduser("~/.gemini/programmes"))
PROGRAMMES_DIR.mkdir(parents=True, exist_ok=True)
PROGRAMME_SCHEMA_PATH = Path("C:/dev/JoshSupervisor/programme_schema.json")


def load_schema():
    with open(SCHEMA_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

def atomic_write(path: Path, data: dict):
    # Validate against schema before writing
    schema = load_schema()
    try:
        jsonschema.validate(instance=data, schema=schema)
    except jsonschema.exceptions.ValidationError as e:
        raise ValueError(f"Mission state failed schema validation: {e.message}")

    temp_path = path.with_suffix(".tmp")
    with open(temp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(temp_path, path)

@mcp.tool()
def get_active_mission() -> dict:
    """Returns the active mission state based on strict rules."""
    resumable = []
    blocked = []
    ask_josh = []
    corrupted = []
    
    schema = load_schema()
    for f in MISSIONS_DIR.glob("*.json"):
        if f.suffix == ".tmp": continue
        try:
            with open(f, "r", encoding="utf-8") as file:
                data = json.load(file)
            jsonschema.validate(instance=data, schema=schema)
            
            st = data.get("current_status")
            if st in ["PENDING", "RUNNING"]:
                resumable.append(data)
            elif st == "BLOCKED":
                blocked.append(data)
            elif st == "ASK_JOSH":
                ask_josh.append(data)
        except Exception as e:
            corrupted.append({"file": str(f), "error": str(e)})
            
    if corrupted:
        return {"status": "corrupted", "details": corrupted}
        
    if len(resumable) == 1:
        return {"status": "success", "mission": resumable[0]}
    elif len(resumable) > 1:
        return {"status": "ambiguous", "message": "Multiple resumable missions found. Ask Josh for priority."}
    
    if ask_josh:
        return {"status": "ask_josh", "missions": ask_josh}
    if blocked:
        return {"status": "blocked", "missions": blocked}
        
    return {"status": "no_active_mission"}

@mcp.tool()
def start_mission(goal: str, constraints: list[str] = None, completion_criteria: list[str] = None) -> dict:
    mission_id = str(uuid.uuid4())
    now = datetime.datetime.utcnow().isoformat()
    mission = {
        "mission_id": mission_id,
        "original_goal": goal,
        "constraints": constraints or [],
        "completion_criteria": completion_criteria or [],
        "current_status": "PENDING",
        "current_plan": "",
        "completed_steps": [],
        "pending_steps": [],
        "blocked_steps": [],
        "evidence_collected": [],
        "reviewer_verdicts": [],
        "unresolved_questions": [],
        "last_trustworthy_checkpoint": "Mission started.",
        "next_recommended_action": "Derive next bounded action.",
        "timestamps": {
            "created_at": now,
            "updated_at": now
        }
    }
    
    try:
        atomic_write(MISSIONS_DIR / f"{mission_id}.json", mission)
        return {"status": "success", "mission_id": mission_id}
    except Exception as e:
        return {"error": str(e)}

@mcp.tool()
def update_mission(
    mission_id: str,
    status: str = None,
    current_plan: str = None,
    completed_step: str = None,
    pending_steps: list[str] = None,
    blocked_step: str = None,
    evidence: str = None,
    reviewer_verdict: str = None,
    checkpoint: str = None,
    next_action: str = None,
    unresolved_question: str = None,
    completion_criteria: list[str] = None
) -> dict:
    path = MISSIONS_DIR / f"{mission_id}.json"
    if not path.exists():
        return {"error": f"Mission {mission_id} not found."}
        
    try:
        with open(path, "r", encoding="utf-8") as f:
            mission = json.load(f)
            
        if status: mission["current_status"] = status
        if current_plan: mission["current_plan"] = current_plan
        if completed_step: 
            if completed_step not in mission["completed_steps"]:
                mission["completed_steps"].append(completed_step)
            if pending_steps is None:
                mission["pending_steps"] = [p for p in mission.get("pending_steps", []) if p != completed_step]
        if pending_steps is not None: mission["pending_steps"] = pending_steps
        if blocked_step: mission["blocked_steps"].append(blocked_step)
        if evidence: mission["evidence_collected"].append(evidence)
        if reviewer_verdict: mission["reviewer_verdicts"].append(reviewer_verdict)
        if checkpoint: mission["last_trustworthy_checkpoint"] = checkpoint
        if next_action: mission["next_recommended_action"] = next_action
        if unresolved_question: mission["unresolved_questions"].append(unresolved_question)
        if completion_criteria is not None: mission["completion_criteria"] = completion_criteria
        
        mission["timestamps"]["updated_at"] = datetime.datetime.utcnow().isoformat()
        
        atomic_write(path, mission)
        return {"status": "success", "mission": mission}
    except Exception as e:
        return {"error": str(e)}


def load_programme_schema():
    with open(PROGRAMME_SCHEMA_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

def atomic_write_programme(path: Path, data: dict):
    schema = load_programme_schema()
    try:
        jsonschema.validate(instance=data, schema=schema)
    except jsonschema.exceptions.ValidationError as e:
        raise ValueError(f"Programme state failed schema validation: {e.message}")

    temp_path = path.with_suffix(".tmp")
    with open(temp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(temp_path, path)

@mcp.tool()
def get_active_programme() -> dict:
    """Returns the active programme state based on strict rules."""
    resumable = []
    blocked = []
    ask_josh = []
    corrupted = []
    
    schema = load_programme_schema()
    for f in PROGRAMMES_DIR.glob("*.json"):
        if f.suffix == ".tmp": continue
        try:
            with open(f, "r", encoding="utf-8") as file:
                data = json.load(file)
            jsonschema.validate(instance=data, schema=schema)
            
            st = data.get("current_status")
            if st in ["PENDING", "RUNNING"]:
                resumable.append(data)
            elif st == "BLOCKED":
                blocked.append(data)
            elif st == "ASK_JOSH":
                ask_josh.append(data)
        except Exception as e:
            corrupted.append({"file": str(f), "error": str(e)})
            
    if corrupted:
        return {"status": "corrupted", "details": corrupted}
        
    if len(resumable) == 1:
        return {"status": "success", "programme": resumable[0]}
    elif len(resumable) > 1:
        return {"status": "ambiguous", "message": "Multiple resumable programmes found. Ask Josh for priority."}
    
    if ask_josh:
        return {"status": "ask_josh", "programmes": ask_josh}
    if blocked:
        return {"status": "blocked", "programmes": blocked}
        
    return {"status": "no_active_programme"}

@mcp.tool()
def start_programme(goal: str, constraints: list[str] = None, completion_criteria: list[str] = None, ordered_mission_queue: list[str] = None) -> dict:
    prog_id = str(uuid.uuid4())
    now = datetime.datetime.utcnow().isoformat()
    prog = {
        "programme_id": prog_id,
        "overall_goal": goal,
        "constraints": constraints or [],
        "completion_criteria": completion_criteria or [],
        "current_status": "PENDING",
        "ordered_mission_queue": ordered_mission_queue or [],
        "completed_missions": [],
        "current_mission": "",
        "blocked_missions": [],
        "unresolved_decisions": [],
        "evidence_summary": [],
        "next_recommended_mission": ordered_mission_queue[0] if ordered_mission_queue else "",
        "timestamps": {
            "created_at": now,
            "updated_at": now
        }
    }
    
    try:
        atomic_write_programme(PROGRAMMES_DIR / f"{prog_id}.json", prog)
        return {"status": "success", "programme_id": prog_id}
    except Exception as e:
        return {"error": str(e)}

@mcp.tool()
def update_programme(
    programme_id: str,
    status: str = None,
    ordered_mission_queue: list[str] = None,
    completed_mission: str = None,
    current_mission: str = None,
    blocked_mission: str = None,
    unresolved_decision: str = None,
    evidence: str = None,
    next_recommended_mission: str = None,
    completion_criteria: list[str] = None
) -> dict:
    path = PROGRAMMES_DIR / f"{programme_id}.json"
    if not path.exists():
        return {"error": f"Programme {programme_id} not found."}
        
    try:
        with open(path, "r", encoding="utf-8") as f:
            prog = json.load(f)
            
        if status: prog["current_status"] = status
        if ordered_mission_queue is not None: prog["ordered_mission_queue"] = ordered_mission_queue
        if completed_mission: 
            if completed_mission not in prog.get("completed_missions", []):
                prog["completed_missions"].append(completed_mission)
            if prog.get("ordered_mission_queue"):
                prog["ordered_mission_queue"] = [m for m in prog["ordered_mission_queue"] if m != completed_mission]
        if current_mission is not None: prog["current_mission"] = current_mission
        if blocked_mission: prog["blocked_missions"].append(blocked_mission)
        if unresolved_decision: prog["unresolved_decisions"].append(unresolved_decision)
        if evidence: prog["evidence_summary"].append(evidence)
        if next_recommended_mission is not None: prog["next_recommended_mission"] = next_recommended_mission
        if completion_criteria is not None: prog["completion_criteria"] = completion_criteria
        
        prog["timestamps"]["updated_at"] = datetime.datetime.utcnow().isoformat()
        
        atomic_write_programme(path, prog)
        return {"status": "success", "programme": prog}
    except Exception as e:
        return {"error": str(e)}

if __name__ == "__main__":
    mcp.run()

